Lemma art_at_ecall_mmap2 : art_at_ecall ASEGS (0x92e60 : word).
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;Y5;00;A1;i25;A1;o26;#0;A1;i27;#1;A2;k28;k29;A3;o30;A1;o26;Y6;00;A1;o10;Y19;12e60;o31;A4;o24;#1;Lw;R#1;A2;i16;A3;i17;#2;#3;A2;o32;#1;r1;A3;i17;i1;A1;k33;r1;o34;k35;A4;o36;A3;i17;#2;#3;A2;o32;#1;k35;A3;i17;i1;A1;k33;k35;o34;k37;k38;").
Qed.

Lemma art_sh_bounds : forall r msz, r mod 4096 = 0 -> msz mod 4096 = 0 -> 0 <= r -> 0 <= msz -> r + msz <= 2 ^ 47 ->
